def install_deadline(apps, schema_editor):
    db = schema_editor.connection.alias
    types = apps.get_model("radar", "ObjectType")
    definitions = apps.get_model("radar", "PropertyDefinition")
    states = apps.get_model("radar", "WorkspaceSchemaState")
    changed = {}
    for kind in types.objects.using(db).filter(key="action", is_system=True):
        row = definitions.objects.using(db).filter(object_type=kind, key="due_at", deleted_at__isnull=True).first()
        if row is None:
            row = definitions.objects.using(db).create(
                workspace_id=kind.workspace_id, object_type=kind, key="due_at", is_system=True, **DEADLINE
            )
            changed[kind.workspace_id] = row
    for state in states.objects.using(db).filter(workspace_id__in=changed):
        row = changed[state.workspace_id]
        base = dict(state.installed_base or {})
        ids = dict(base.get("ids", {}))
        specs = dict(base.get("definitions", {}))
        if ids.get("types:action") == str(row.object_type_id):
            specs["properties:action.due_at"] = DEADLINE
            ids["properties:action.due_at"] = str(row.pk)
        base.update(ids=ids, definitions=specs)
        states.objects.using(db).filter(pk=state.pk).update(installed_base=base, revision=state.revision + 1)


